/* LE COURRIEL ET LE TÉLÉPHONE : écrits une seule fois, en haut de index.html (window.CONTACT) */
var CONTACT = window.CONTACT || {};
var COURRIEL = CONTACT.courriel || "";
var TELEPHONE = CONTACT.telephone || "";
var TEL_LIEN = (function () {   // « 514 000 0000 » → « +15140000000 » (le lien qui ouvre l'appel)
  var c = TELEPHONE.replace(/[^0-9]/g, "");
  return c.length === 10 ? "+1" + c : (TELEPHONE.trim().charAt(0) === "+" ? "+" : "") + c;
})();
function remplirContact(frag) {
  [].forEach.call(frag.querySelectorAll("[data-contact]"), function (a) {
    var tel = a.getAttribute("data-contact") === "telephone";
    a.setAttribute("href", tel ? "tel:" + TEL_LIEN : "mailto:" + COURRIEL);
    var s = a.querySelector("span"); if (s) s.textContent = tel ? TELEPHONE : COURRIEL;
  });
}



